// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Signer maker;
    MockERC20 base;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new Signer();
        base = new MockERC20();
        vm.warp(1_000_000);
    }

    function testFuzz_property(uint256 premium, uint256 strike, uint256 duration) public {
        premium = bound(premium, 0, 1e30);
        strike = bound(strike, 0, 1e30);
        duration = bound(duration, 1, 10_000 days - 1);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: false,
            baseAsset: address(base),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);

        base.approve(address(c), type(uint256).max);

        uint256 positionId = c.fillOrder(order, "", floorAssetTokenIds);

        // General rule: the id returned by fillOrder is the id of the counter-position,
        // i.e. the hash of the order with isLong flipped, which was minted to the taker.
        assertTrue(positionId == uint256(c.hashOppositeOrder(order)));
    }
}

contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract MockERC20 {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
